/**
 * Runtime validation for Pina's zeropod wire types.
 *
 * This file is generated by `pina codama generate`. The stock Codama codecs
 * intentionally permit truncation and permissive decoding, whereas Pina's
 * on-chain zeropod views reject those non-canonical representations.
 */

import {
	addDecoderSizePrefix,
	type Encoder,
	fixDecoderSize,
	type FixedSizeDecoder,
	type FixedSizeEncoder,
	fixEncoderSize,
	getBytesDecoder,
	getU8Decoder,
	transformDecoder,
	transformEncoder,
} from "@solana/kit";

type Integer = bigint | number;

/** Pads valid values but rejects values that would otherwise be truncated. */
export function fixZeroPodEncoderSize<TFrom, TSize extends number>(
	encoder: Encoder<TFrom>,
	fixedBytes: TSize,
): FixedSizeEncoder<TFrom, TSize> {
	const checkedEncoder = transformEncoder(encoder, (value: TFrom) => {
		const encodedSize = "fixedSize" in encoder
			? encoder.fixedSize
			: encoder.getSizeFromValue(value);
		if (encodedSize > fixedBytes) {
			throw new RangeError(
				`zeropod value needs ${encodedSize} bytes but its capacity is ${fixedBytes}`,
			);
		}
		return value;
	});

	return fixEncoderSize(checkedEncoder, fixedBytes);
}

/** Decodes UTF-8 strictly and preserves embedded NUL characters. */
export function getZeroPodStringDecoder<TSize extends number>(
	prefix: FixedSizeDecoder<bigint> | FixedSizeDecoder<number>,
	fixedBytes: TSize,
): FixedSizeDecoder<string, TSize> {
	const bytes = addDecoderSizePrefix(getBytesDecoder(), prefix);
	return transformDecoder(
		fixDecoderSize(bytes, fixedBytes),
		(value) => new TextDecoder("utf-8", { fatal: true }).decode(value),
	);
}

/** Accepts only zeropod's canonical boolean encodings. */
export function getZeroPodBooleanDecoder(): FixedSizeDecoder<boolean, 1> {
	return transformDecoder(getU8Decoder(), (value) => {
		if (value !== 0 && value !== 1) {
			throw new RangeError(`invalid zeropod boolean: ${value}`);
		}
		return value === 1;
	});
}

/** Rejects data for a different account or instruction before decoding it. */
export function getZeroPodDiscriminatorDecoder<
	TDecoded extends Integer,
	TSize extends number,
>(
	expected: Integer,
	decoder: FixedSizeDecoder<TDecoded, TSize>,
): FixedSizeDecoder<TDecoded, TSize> {
	return transformDecoder(decoder, (value) => {
		if (BigInt(value) !== BigInt(expected)) {
			throw new RangeError(
				`invalid discriminator: expected ${expected}, received ${value}`,
			);
		}
		return value;
	});
}

/** Rejects numeric enum representations not declared by the native schema. */
export function getZeroPodEnumDecoder<
	TValue extends number,
	TSize extends number,
>(
	decoder: FixedSizeDecoder<TValue, TSize>,
	validValues: readonly TValue[],
): FixedSizeDecoder<TValue, TSize> {
	return transformDecoder(decoder, (value) => {
		if (!validValues.includes(value)) {
			throw new RangeError(`invalid zeropod enum discriminant: ${value}`);
		}
		return value;
	});
}
